{"file_path":"src/parse.js","content":"export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

const WORD = /^[A-Za-z0-9_./:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null

  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const t = line.split(/\s+/)
    const fail = (m) => { throw new ParseError(n, m) }
    const num = (field, v, least) => {
      if (!COUNT.test(v) || BigInt(v) < BigInt(least)) fail(`${field} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const word = t[0]
    if (word !== 'bucket' && word !== 'window' && word !== 'route' && word !== 'event') {
      fail(`unknown directive ${word}`)
    }
    if (word !== 'event' && events.length > 0) fail('declarations must come before the first event')
    if (word === 'bucket') {
      if (t.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
      if (!WORD.test(t[1])) fail(`invalid policy name ${t[1]}`)
      const capacity = num('capacity', t[2], 1)
      const refill = num('refill', t[3], 0)
      const per = num('per', t[4], 1)
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'bucket', name: t[1], capacity, refill, per })
    } else if (word === 'window') {
      if (t.length !== 4) fail('expected window <name> <limit> <span>')
      if (!WORD.test(t[1])) fail(`invalid policy name ${t[1]}`)
      const limit = num('limit', t[2], 0)
      const span = num('span', t[3], 1)
      if (policies.has(t[1])) fail(`policy ${t[1]} is declared twice`)
      policies.set(t[1], { kind: 'window', name: t[1], limit, span })
    } else if (word === 'route') {
      if (t.length < 3) fail('expected route <prefix> <policy>...')
      if (!WORD.test(t[1])) fail(`invalid route prefix ${t[1]}`)
      if (routes.has(t[1])) fail(`prefix ${t[1]} is routed twice`)
      for (const p of t.slice(2)) if (!policies.has(p)) fail(`unknown policy ${p}`)
      routes.set(t[1], t.slice(2))
    } else {
      if (t.length !== 3) fail('expected event <tick> <key>')
      const tick = num('tick', t[1], 0)
      if (!WORD.test(t[2])) fail(`invalid key ${t[2]}`)
      if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      events.push({ tick, key: t[2] })
    }
  })
  return { policies, routes, events }
}
"}

